def test_point_opacity_encoding_all_null():
    """All-null opacity column falls back to default, not crash."""
    df = pl.DataFrame(
        {"x": [1.0, 2.0, 3.0], "y": [10.0, 20.0, 30.0], "op": [None, None, None]},
        schema={"x": pl.Float64, "y": pl.Float64, "op": pl.Float64},
    )
    chart = fr.Chart(df).mark_point().encode(x="x", y="y", opacity="op")
    svg = chart.show_svg()
    assert not _has_nan_in_svg(svg)
    assert svg.count("<circle") >= 3


def test_point_stroke_width_negative_ignored():
    """Negative stroke_width in encoding should be ignored (fall to default)."""
    df = pl.DataFrame(
        {
            "x": [1.0, 2.0, 3.0],
            "y": [10.0, 20.0, 30.0],
            "sw": [-1.0, 2.0, -5.0],
        }
    )
    chart = fr.Chart(df).mark_point().encode(x="x", y="y", stroke_width="sw")
    svg = chart.show_svg()
    assert 'stroke-width="-' not in svg
    assert not _has_nan_in_svg(svg)


def test_point_fill_opacity_nan_falls_back():
    """NaN in fill_opacity encoding falls back to 1.0."""
    df = pl.DataFrame(
        {
            "x": [1.0, 2.0, 3.0],
            "y": [10.0, 20.0, 30.0],
            "fo": [0.3, float("nan"), 0.7],
        }
    )
    chart = fr.Chart(df).mark_point().encode(x="x", y="y", fill_opacity="fo")
    svg = chart.show_svg()
    assert not _has_nan_in_svg(svg)


