# 9. Text mark
# ---------------------------------------------------------------------------


def test_text_mark_renders_labels():
    """mark_text should render text elements for each row."""
    df = pl.DataFrame(
        {
            "x": [1.0, 2.0, 3.0],
            "y": [10.0, 20.0, 30.0],
            "label": ["Alpha", "Beta", "Gamma"],
        }
    )
    chart = fr.Chart(df).mark_text().encode(x="x", y="y", text="label")
    svg = chart.show_svg()
    assert svg.startswith("<svg")
    assert ">Alpha<" in svg or ">Alpha</text>" in svg
    assert ">Beta<" in svg or ">Beta</text>" in svg
    assert ">Gamma<" in svg or ">Gamma</text>" in svg


def test_text_mark_with_axis_object():
    """mark_text with Axis(...) on x encoding should not crash."""
    df = pl.DataFrame(
        {
            "x": [1.0, 2.0, 3.0],
            "y": [10.0, 20.0, 30.0],
            "label": ["A", "B", "C"],
        }
    )
    chart = (
        fr.Chart(df)
        .mark_text()
        .encode(x=fr.X("x", axis=fr.Axis(title="X Axis")), y="y", text="label")
    )
    svg = chart.show_svg()
    assert svg.startswith("<svg")
    assert not _has_nan_in_svg(svg)
    # Axis title should appear
    assert "X Axis" in svg


